import{_ as e,o as r,c as a,ag as d}from"./chunks/framework.Aev9KvMf.js";const f=JSON.parse('{"title":"成人脑卒中食养指南（2026年版）","description":"国家卫健委《成人脑卒中食养指南（2026年版）》可执行整理：按恢复期/后遗症期实施的食养行动清单，每条出处可一键跳回原文对应页。","frontmatter":{"title":"成人脑卒中食养指南（2026年版）","issuer":"国家卫生健康委办公厅","source_tier":"一级来源","version":"2026年版","published":"2026-04","source_url":"https://www.nhc.gov.cn/sps/c100087/202604/a69d2fce21e040dc96cbc40b923a06d3.shtml","status":"现行","tags":["脑卒中","食养","吞咽障碍","饮食指导","行动清单"],"reviewed":false,"description":"国家卫健委《成人脑卒中食养指南（2026年版）》可执行整理：按恢复期/后遗症期实施的食养行动清单，每条出处可一键跳回原文对应页。"},"headers":[],"relativePath":"guides/stroke-2026.md","filePath":"guides/stroke-2026.md"}'),s={name:"guides/stroke-2026.md"};function o(g,t,h,i,n,l){return r(),a("div",null,[...t[0]||(t[0]=[d('<h1 id="成人脑卒中食养指南-2026年版" tabindex="-1">成人脑卒中食养指南（2026年版） <a class="header-anchor" href="#成人脑卒中食养指南-2026年版" aria-label="Permalink to &quot;成人脑卒中食养指南（2026年版）&quot;">​</a></h1><div class="warning custom-block"><p class="custom-block-title">初稿待人工校验</p><p>本页由 AI 依据官方 PDF 原文整理，尚未逐条对照原文校验；校验通过前请以原文为准。</p></div><div class="danger custom-block"><p class="custom-block-title">使用须知</p><p>本页所有建议均<strong>整理自官方文件原文</strong>，每条&quot;出处&quot;均可点击直达原文对应页；标注【本站提示】的少数条目为中性工具提示，不代表医学建议。本站不构成诊疗建议，与医生的治疗方案冲突时，<strong>以医嘱为准</strong>。</p></div><blockquote><p><strong>原文出处</strong>：国家卫生健康委办公厅印发（<a href="https://www.nhc.gov.cn/sps/c100087/202604/a69d2fce21e040dc96cbc40b923a06d3.shtml" target="_blank" rel="noreferrer">通知页</a>）· 一级来源。下文&quot;出处&quot;链接指向本站镜像的<a href="https://yshuai.github.io/SageRelay/guides-pdf/stroke-2026.pdf" target="_blank" rel="noreferrer">官方原文 PDF</a>（政府公文，属公共领域）。</p></blockquote><h2 id="这份文件适合谁" tabindex="-1">这份文件适合谁 <a class="header-anchor" href="#这份文件适合谁" aria-label="Permalink to &quot;这份文件适合谁&quot;">​</a></h2><p>脑卒中恢复期、后遗症期患者及其照护者，以及卒中高危人群（<a href="https://yshuai.github.io/SageRelay/guides-pdf/stroke-2026.pdf#page=5" target="_blank" rel="noreferrer">原文·前言</a>）。<strong>吞咽障碍者的食物质地调整须先经专业评估（附录5 有筛查方法）。</strong></p><h2 id="速览卡-一屏看完" tabindex="-1">速览卡（一屏看完） <a class="header-anchor" href="#速览卡-一屏看完" aria-label="Permalink to &quot;速览卡（一屏看完）&quot;">​</a></h2><p><strong>七条原则</strong>：能量适宜蛋白优质、调控脂肪和碳水 → 调钾补钙多维生素、保护神经与血管 → 食物多样清淡烹饪、质地软烂易吞咽 → 适量饮水限制饮酒、合理增稠防呛咳 → 辨体辨证饮食有节 → 尽早活动全面训练 → 心理支持康养结合。（<a href="https://yshuai.github.io/SageRelay/guides-pdf/stroke-2026.pdf#page=8" target="_blank" rel="noreferrer">原文·三</a>）</p><table tabindex="0"><thead><tr><th>关键数字（每日，除注明外）</th><th>数值</th><th>出处</th></tr></thead><tbody><tr><td>能量</td><td>卧床约 <strong>20～25kcal/kg</strong>；轻度活动约 <strong>30kcal/kg</strong>；中度活动约 <strong>35kcal/kg</strong></td><td><a href="https://yshuai.github.io/SageRelay/guides-pdf/stroke-2026.pdf#page=8" target="_blank" rel="noreferrer">三(一)</a></td></tr><tr><td>蛋白质</td><td>供能 <strong>15%～20%</strong>，至少 <strong>1.0g/kg</strong>；高分解代谢状态（压疮、感染）增至 <strong>1.2～1.5g/kg</strong></td><td><a href="https://yshuai.github.io/SageRelay/guides-pdf/stroke-2026.pdf#page=8" target="_blank" rel="noreferrer">三(一)</a></td></tr><tr><td>鱼虾类</td><td><strong>每周 300～500g</strong></td><td><a href="https://yshuai.github.io/SageRelay/guides-pdf/stroke-2026.pdf#page=8" target="_blank" rel="noreferrer">三(一)</a></td></tr><tr><td>畜禽肉</td><td>每天约 <strong>50g</strong></td><td><a href="https://yshuai.github.io/SageRelay/guides-pdf/stroke-2026.pdf#page=8" target="_blank" rel="noreferrer">三(一)</a></td></tr><tr><td>鸡蛋</td><td><strong>每天 1 个</strong></td><td><a href="https://yshuai.github.io/SageRelay/guides-pdf/stroke-2026.pdf#page=8" target="_blank" rel="noreferrer">三(一)</a></td></tr><tr><td>大豆</td><td><strong>每周 100～175g</strong> 或相当量豆制品</td><td><a href="https://yshuai.github.io/SageRelay/guides-pdf/stroke-2026.pdf#page=8" target="_blank" rel="noreferrer">三(一)</a></td></tr><tr><td>烹调油</td><td><strong>≤25g</strong>，主要来源为植物油</td><td><a href="https://yshuai.github.io/SageRelay/guides-pdf/stroke-2026.pdf#page=8" target="_blank" rel="noreferrer">三(一)</a></td></tr><tr><td>膳食纤维</td><td><strong>25～30g</strong></td><td><a href="https://yshuai.github.io/SageRelay/guides-pdf/stroke-2026.pdf#page=8" target="_blank" rel="noreferrer">三(二)</a></td></tr><tr><td>蔬菜</td><td><strong>300g 以上</strong>，深色蔬菜为主</td><td><a href="https://yshuai.github.io/SageRelay/guides-pdf/stroke-2026.pdf#page=8" target="_blank" rel="noreferrer">三(二)</a></td></tr><tr><td>食盐</td><td><strong>&lt;5g</strong></td><td><a href="https://yshuai.github.io/SageRelay/guides-pdf/stroke-2026.pdf#page=8" target="_blank" rel="noreferrer">三(二)</a></td></tr></tbody></table><h2 id="行动清单" tabindex="-1">行动清单 <a class="header-anchor" href="#行动清单" aria-label="Permalink to &quot;行动清单&quot;">​</a></h2><h3 id="🍚-吃" tabindex="-1">🍚 吃 <a class="header-anchor" href="#🍚-吃" aria-label="Permalink to &quot;🍚 吃&quot;">​</a></h3><table tabindex="0"><thead><tr><th>怎么做</th><th>出处</th></tr></thead><tbody><tr><td>食物多样、清淡烹饪、质地软烂易吞咽</td><td><a href="https://yshuai.github.io/SageRelay/guides-pdf/stroke-2026.pdf#page=8" target="_blank" rel="noreferrer">三(三)</a></td></tr><tr><td>适量饮水、限制饮酒；吞咽障碍者<strong>合理增稠防呛咳</strong>（食物质地分级见附录6）</td><td><a href="https://yshuai.github.io/SageRelay/guides-pdf/stroke-2026.pdf#page=8" target="_blank" rel="noreferrer">三(四)</a>、<a href="https://yshuai.github.io/SageRelay/guides-pdf/stroke-2026.pdf#page=102" target="_blank" rel="noreferrer">附录6</a></td></tr><tr><td>辨体辨证、饮食有节，按中医证型选食药物质与食养方</td><td><a href="https://yshuai.github.io/SageRelay/guides-pdf/stroke-2026.pdf#page=8" target="_blank" rel="noreferrer">三(五)</a>、<a href="https://yshuai.github.io/SageRelay/guides-pdf/stroke-2026.pdf#page=86" target="_blank" rel="noreferrer">附录4</a></td></tr><tr><td>减少酱油、鸡精等含钠调味品</td><td><a href="https://yshuai.github.io/SageRelay/guides-pdf/stroke-2026.pdf#page=8" target="_blank" rel="noreferrer">三(二)</a></td></tr></tbody></table><h3 id="🏃-动-🩺-测与就医" tabindex="-1">🏃 动 / 🩺 测与就医 <a class="header-anchor" href="#🏃-动-🩺-测与就医" aria-label="Permalink to &quot;🏃 动 / 🩺 测与就医&quot;">​</a></h3><table tabindex="0"><thead><tr><th>怎么做</th><th>出处</th></tr></thead><tbody><tr><td>尽早活动、全面训练，长期坚持助复健</td><td><a href="https://yshuai.github.io/SageRelay/guides-pdf/stroke-2026.pdf#page=8" target="_blank" rel="noreferrer">三(六)</a></td></tr><tr><td>心理支持、康养结合；四季养生以冬季为主</td><td><a href="https://yshuai.github.io/SageRelay/guides-pdf/stroke-2026.pdf#page=8" target="_blank" rel="noreferrer">三(七)</a></td></tr><tr><td>吞咽障碍先做分级筛查与评估（附录5），再确定食物质地</td><td><a href="https://yshuai.github.io/SageRelay/guides-pdf/stroke-2026.pdf#page=101" target="_blank" rel="noreferrer">附录5</a></td></tr></tbody></table><h2 id="附录怎么用" tabindex="-1">附录怎么用 <a class="header-anchor" href="#附录怎么用" aria-label="Permalink to &quot;附录怎么用&quot;">​</a></h2><ul><li><strong><a href="https://yshuai.github.io/SageRelay/guides-pdf/stroke-2026.pdf#page=19" target="_blank" rel="noreferrer">附录1《食物选择》</a></strong> · <strong><a href="https://yshuai.github.io/SageRelay/guides-pdf/stroke-2026.pdf#page=20" target="_blank" rel="noreferrer">附录2《常见食物交换表》</a></strong> · <strong><a href="https://yshuai.github.io/SageRelay/guides-pdf/stroke-2026.pdf#page=24" target="_blank" rel="noreferrer">附录3《不同地区不同季节食谱示例》</a></strong> · <strong><a href="https://yshuai.github.io/SageRelay/guides-pdf/stroke-2026.pdf#page=86" target="_blank" rel="noreferrer">附录4《证型食养方举例》</a></strong> · <strong><a href="https://yshuai.github.io/SageRelay/guides-pdf/stroke-2026.pdf#page=101" target="_blank" rel="noreferrer">附录5《吞咽障碍分级筛查和评估方法》</a></strong> · <strong><a href="https://yshuai.github.io/SageRelay/guides-pdf/stroke-2026.pdf#page=102" target="_blank" rel="noreferrer">附录6《食物质地分级与食品选择》</a></strong>。</li></ul><h2 id="原文与溯源" tabindex="-1">原文与溯源 <a class="header-anchor" href="#原文与溯源" aria-label="Permalink to &quot;原文与溯源&quot;">​</a></h2><table tabindex="0"><thead><tr><th>字段</th><th>内容</th></tr></thead><tbody><tr><td>发布机构</td><td>国家卫生健康委办公厅</td></tr><tr><td>版本</td><td>2026 年版（现行）</td></tr><tr><td>印发时间</td><td>2026 年 4 月</td></tr><tr><td>原文直链</td><td><a href="https://www.nhc.gov.cn/sps/c100087/202604/a69d2fce21e040dc96cbc40b923a06d3.shtml" target="_blank" rel="noreferrer">卫健委通知页</a></td></tr></tbody></table>',18)])])}const u=e(s,[["render",o]]);export{f as __pageData,u as default};
